Apply a bounded batch of live source changes; save=true persists the batch afterward. Changes remain live on compile failure, attachments are outside this batch, and game hot reload is not promised. Validation snapshots exclude caches/symlinks and are limited to 512 MiB and 20,000 files.

exec tool declaration:
```ts
declare const tools: { mcp__godot__apply_script_changes(args: {
  changes: Array<{ create?: { source: string; uri: string; }; edit?: { edits: Array<{ range: { end: { column: number; line: number; }; start: { column: number; line: number; }; }; text: string; }>; if_revision: string; uri: string; }; replace?: { if_revision: string; source: string; uri: string; }; }>;
  // Absolute project path; omit after selecting via get_context.
  project?: string;
  // Persist the whole batch after application; false leaves live drafts.
  save?: boolean;
}): Promise<CallToolResult<{
  attachments?: Array<{ path?: string; property?: string; resource?: string; scene?: string; }>;
  // The detailed snapshot is currently retained; query get_operation_result before the session or retention window ends.
  details_retained: boolean;
  documents: Array<{ applied_revision?: string; base_disk_revision?: string | null; baseline_known?: boolean; conflict?: "none" | "external_change" | "baseline_unknown"; disk_revision?: string | null; effect?: "created" | "updated" | "saved"; live_reload?: "succeeded" | "failed" | "deferred" | "not_attempted"; revision?: string | null; save?: { previous_uri?: string; requested?: boolean; state: "saved" | "failed" | "skipped"; target?: string; }; state?: "saved" | "modified" | "draft" | "unavailable"; uri: string; validation?: {
  checked_state?: "valid" | "invalid";
  // Checked revision when different from the containing document; omitted means that document revision.
  revision?: string | null;
  state: "valid" | "invalid" | "pending" | "unavailable";
}; }>;
  failures?: Array<{ code: string; details?: { [key: string]: unknown; }; message: string; node?: { path: string; scene: string; }; phase: string; recovery?: { arguments: { [key: string]: unknown; }; prerequisite?: string; tool: string; }; resource?: string; uri?: string; [key: string]: unknown; }>;
  operation_id: string;
  pending?: Array<string>;
  pending_save?: Array<string>;
  project?: string;
  status: "completed" | "partial" | "failed";
  undo?: { edit_id?: string | null; retained_files?: Array<string>; scope?: Array<string>; };
} | { error: { code: string; details: { [key: string]: unknown; }; message: string; [key: string]: unknown; }; [key: string]: unknown; }>>; };
```

